#include <iostream>

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

void findPredecessorSuccessor(Node* root, int key, Node*& pre, Node*& succ) {
    if (root == nullptr) return;

    // If key is present at root
    if (root->data == key) {
        // Predecessor is the rightmost node of left subtree
        if (root->left != nullptr) {
            Node* temp = root->left;
            while (temp->right != nullptr) temp = temp->right;
            pre = temp;
        }
        // Successor is the leftmost node of right subtree
        if (root->right != nullptr) {
            Node* temp = root->right;
            while (temp->left != nullptr) temp = temp->left;
            succ = temp;
        }
        return;
    }

    // If key is smaller than root's key, go to left subtree
    if (key < root->data) {
        succ = root; // root is a candidate for successor
        findPredecessorSuccessor(root->left, key, pre, succ);
    } else {
        pre = root;  // root is a candidate for predecessor
        findPredecessorSuccessor(root->right, key, pre, succ);
    }
}
